import json,gzip,pathlib,re,hashlib,datetime,sys
D=pathlib.Path('docs/det-engine/v19');state=json.loads((D/'state.json').read_text());cycle=state['currentCycle'];now=datetime.datetime.now(datetime.timezone.utc);assert now<datetime.datetime.fromisoformat(state['hardDeadline'].replace('Z','+00:00'));cs=json.loads((D/f'cycle-{cycle}/state.json').read_text());assert cs['status']=='in_progress_no_go'and now<datetime.datetime.fromisoformat(cs['deadline'].replace('Z','+00:00'));out=pathlib.Path(sys.argv[1]);assert out.resolve().is_relative_to((D/f'cycle-{cycle}/evidence').resolve())and not out.exists();out.mkdir()
def load(p):return[json.loads(l)for l in gzip.open(p,'rt')]
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
C=load('docs/det-engine/v16/evidence/final/canonical.jsonl.gz');Q={x['legacyId']:x for x in load('docs/det-engine/v17/evidence/qualification-final.jsonl.gz')};bibliography=json.loads(pathlib.Path('docs/det-engine/v8/bibliography.json').read_text());byid={c['identity']['legacyId']:c for c in C}
# Exact DOI/PMID metadata are checked against public responses; full abstracts stay in /tmp.
references=[]
for file,expected_doi,summary,limits in [('/tmp/det-v19-cooldown.json','10.1007/s40279-018-0916-2','La revue narrative ne montre pas un bénéfice général des retours au calme actifs sur la plupart des marqueurs de récupération. Certains bénéfices restent possibles.','Ne valide pas une récupération finale de cinq minutes dans ce protocole, une meilleure tolérance aux efforts précédents ou un gain individuel.'),('/tmp/det-v19-nutrition-doi.json','10.1007/s40279-017-0690-6','La revue décrit une adaptation digestive et des mécanismes dépendant des nutriments. Elle souligne des incertitudes sur les méthodes et délais optimaux.','Le résumé ne valide ni un départ universel à 60g/h, ni 100–120g/h, ni un ratio obligatoire unique, ni une adaptation acquise après huit semaines.')]:
 raw=json.loads(pathlib.Path(file).read_text());x=next(x for x in raw['resultList']['result']if x.get('doi')==expected_doi);abstract=re.sub('<[^>]+>','',x['abstractText']);references.append({'doi':x['doi'],'pmid':x['id'],'title':x['title'],'authors':x['authorString'],'year':x['pubYear'],'url':'https://pubmed.ncbi.nlm.nih.gov/'+x['id']+'/','publicResponseSha256':sha(file),'abstractRead':True,'fullTextRead':False,'summaryFrench':summary,'applicabilityLimits':limits,'shortExcerpt':' '.join(abstract.split()[:28]),'fullAbstractStoredInRepository':False,'individualScientificApproval':False})
assert references[1]['title']=='Training the Gut for Athletes.'
manual=[
 {'legacyId':'C_IM_AERO_HOLD','kind':'final_recovery_causal_scope','contextDOIs':['10.1007/s40279-018-0916-2'],'editorialRevision':'Conserver les 4×15 minutes et les récupérations Z1 de la source. Présenter séparément la récupération finale proposée et le retour au calme éventuel ; aucune branche n’est approuvée.','reviewFinding':'Les variantes 75/80 minutes modifient la dernière récupération, pas la dose des efforts précédents. Le résumé de la revue ne justifie pas une meilleure récupération individuelle par cinq minutes Z1 supplémentaires.','conditions':['choix explicite du coach','tolérance posturale et musculaire actuelle','contraintes du microcycle','réaction observée distincte de l’avis de résistance à la fatigue'],'scientificLevel':'narrative_review_context_not_exact_protocol_validation'},
 {'legacyId':'FATMAX_TRAIN_HIGH_GUT','kind':'conditional_nutritional_progression','contextDOIs':['10.1007/s40279-017-0690-6'],'editorialRevision':'Conserver tous les paliers chiffrés et la consigne de ratio comme données originales, mais les présenter comme propositions historiques non approuvées. Aucun palier supérieur n’est réputé acquis par le seul passage des semaines. Le coach doit confirmer la tolérance au palier courant et décider maintien, refus ou réévaluation ; aucune nouvelle quantité n’est prescrite ici.','reviewFinding':'La publication Jeukendrup 2017 existe et a été relue au niveau du résumé. Ce résumé ne confirme pas l’échéance 8–10 semaines ni la progression précise vers 100–120g/h ni l’universalité du ratio obligatoire. La consigne originale n’est pas supprimée ou remplacée automatiquement.','conditions':['historique de tolérance digestive documenté quand nécessaire','produits et conditions de course','symptômes déjà suivis par le coach','revue compétente avant progression nutritionnelle'],'scientificLevel':'mechanism_plausible_context_dose_and_timeline_unverified'},
 {'legacyId':'NUTRITION_CARB_PERIODIZATION_WEEK','kind':'author_attribution_clarification','contextDOIs':[],'editorialRevision':'Présenter le tableau comme un exemple TFCLab candidat de périodisation glucidique. Distinguer les principes documentés d’individualisation et de feedback de Lorang des jours, quotas de VO2max et quantités alimentaires exacts du tableau. Conserver intégralement le tableau original pour revue.','reviewFinding':'Les entretiens édités L175/L417/L220 examinés en V8 ne prouvent pas ce calendrier alimentaire universel ni une obligation de séance intense chaque mardi. Le contexte Impey 2018 mentionné dans la source n’est pas vérifié par une simple attribution au module.','conditions':['pas de promotion des quantités du tableau','adaptation au profil et à la charge effectivement prévue','revue nutritionnelle et incertitudes'],'scientificLevel':'documented_coaching_principles_distinct_from_TFCL_conventions'},
 {'legacyId':'B_LCW_NUTRITION_RECHARGE','kind':'blocking_unit_context_clarification','contextDOIs':[],'editorialRevision':'Isoler la mention « Hydratation +500 mL/h de sommeil visée » comme une consigne à clarifier, sans en faire une prescription automatique ni la convertir en volume à boire pendant le sommeil. Conserver l’original, demander confirmation de l’unité et de la période d’application. Aucune quantité de remplacement n’est inventée.','reviewFinding':'La portée de cette unité et la manière de l’appliquer sont ambiguës dans un protocole inter-étapes. Cette remarque ne constitue ni un diagnostic clinique ni une nouvelle limite universelle d’hydratation. Le sous-chantier reste bloqué pour prescription/export de cette consigne ; les autres travaux continuent.','conditions':['confirmation de l’auteur ou revue compétente','durée et contexte réellement visés','pas d’activation automatique de cette consigne'],'scientificLevel':'unresolved_high_impact_source_instruction'}]
for case in manual:
 c=byid[case['legacyId']];case.update({'sourceEffectiveHash':c['provenance']['effectiveContentSha256'],'sourceInstructions':c['original']['effective']['structure'],'origin':'new_editorial_proposal','sourceCorrectionApplied':False,'scientificValidation':False,'humanExpertReview':False,'automaticPromotion':False,'newDoseInvented':False})
patterns=[('quantified_adaptation_claim',r'(?:augment|amélior|rédui|gains?|baisse)[^.\n]{0,90}\d+(?:[–-]\d+)?\s*%'),('universal_author_or_protocol_wording',r'\b(?:OBLIGATOIRE|standard or|universel|TOUJOURS|JAMAIS)\b'),('scheduled_adaptation_claim',r'adaptation[^.\n]{0,80}(?:semaines|jours)'),('nutrition_or_fasting_instruction',r'\b(?:g/h|CHO|glucides|à jeun|fasted)\b'),('thermal_or_hypoxic_instruction',r'\b(?:sauna|chaleur|hypoxi|altitude)\w*')]
rows=[]
for c in C:
 legacy=c['identity']['legacyId'];flags=[]
 for i,p in enumerate(c['original']['effective']['structure']):
  for code,pattern in patterns:
   for match in re.finditer(pattern,p['text'],re.I):flags.append({'code':code,'partIndex':i,'sourceExcerpt':match[0],'pythonStart':match.start(),'pythonEnd':match.end(),'status':'review_question_not_a_scientific_finding'})
 selected=[x for x in manual if x['legacyId']==legacy];q=Q[legacy];priority=0 if legacy in ['C_BRICK_TRANSITION_DRILL','V3_RUN_10K_TEMPO_CRUISE','S2R_WALK_RUN_1_2','B_LCW_NUTRITION_RECHARGE']else 1 if q.get('archivedV14Impact')else 2 if selected else 3
 rows.append({'legacyId':legacy,'sourceCanonicalReferences':c['prescription']['references'],'scientificQualificationV17':q,'reviewRoutingFlags':flags,'reviewPriority':priority,'newExplicitlySelectedDocumentaryDossiers':selected,'sourcePhysiologyExplicit':c['prescription']['physiology'],'individualEvidenceNotSupplied':True,'scientificPromotion':False,'expertReview':False,'editorialDoseConventionsAreNotTrialResults':True})
with gzip.GzipFile(out/'scientific-matrix.jsonl.gz','wb',mtime=0)as f:f.write(('\n'.join(json.dumps(r,ensure_ascii=False,separators=(',',':'))for r in rows)+'\n').encode())
(out/'documentary-context.json').write_text(json.dumps({'newPublicAbstractReviews':references,'inheritedV8Bibliography':bibliography,'exactManualCases':manual,'automaticAttributionToOtherWorkouts':False,'lorangContext':'docs/det-engine/v8/LORANG_METHODOLOGY.md; edited shownotes, not universal dose trials','freeResearchDiscarded':[{'query':'title + author field','result':'0 hits'},{'query':'broad training/gut title','result':'newest results on mice and unrelated interventions excluded; no transfer to athlete dosing'}],'paidCalls':0},ensure_ascii=False,indent=2)+'\n')
summary={'records':len(rows),'manualEditorialDossiers':len(manual),'newVerifiedPublicAbstracts':len(references),'sourcePhysiologyExplicit':sum(r['sourcePhysiologyExplicit']is not None for r in rows),'scientificRowsV17Unchanged':920,'individualScientificValidations':0,'humanExpertReviews':0,'automaticReferenceAttributions':0,'reviewRoutingFlagOccurrences':sum(len(r['reviewRoutingFlags'])for r in rows),'sourceCardOrValidatorChanges':0};(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary))
